from gui.styles.theme import TEXT_PRIMARY

def get_icon(icon_name: str, color: str = TEXT_PRIMARY, size: int = 24) -> QIcon:
    """Renders an SVG string to a QIcon with the specified color."""
    svg_string = ICONS.get(icon_name, "")
    if not svg_string:
        return QIcon()
        
    svg_string = svg_string.replace('currentColor', color)
    renderer = QSvgRenderer(QByteArray(svg_string.encode('utf-8')))
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.transparent)
    painter = QPainter(pixmap)
    # Improve rendering quality
    painter.setRenderHint(QPainter.Antialiasing)
    renderer.render(painter)
    painter.end()
    
    return QIcon(pixmap)
